    // Array violating max-heap at index 0 (root=4, left=14, right=7)
    int heap[] = {4, 14, 7, 2, 8, 1};
    int n = sizeof(heap) / sizeof(heap[0]);
    max_heapify(heap, n, 0);

    // After max_heapify at 0: root should be 14, left child 8, right child 7
    assert(heap[0] == 14);
    assert(heap[1] == 8);
    assert(heap[2] == 7);
    assert(heap[3] == 2);
